# Generated by go-anything: the same functions, answered by the Go port over a pipe.
#
#   require_relative 'port'
#   GoPort.count("a b ")   # 2
require 'json'
require 'open3'

module GoPort
  BIN = ENV.fetch('GO_ANYTHING_PORTCTL', File.join(__dir__, 'portctl'))
  LOCK = Mutex.new
  @proc = nil

  def self.proc
    @proc ||= begin
      stdin, stdout, _wait = Open3.popen2(BIN)
      [stdin, stdout]
    end
  end

  def self.decode(v)
    case v
    when Array then v.map { |x| decode(x) }
    when Hash
      if v.size == 1
        case v.keys.first
        when '$number'
          { 'NaN' => Float::NAN, 'Infinity' => Float::INFINITY,
            '-Infinity' => -Float::INFINITY, '-0' => -0.0 }[v['$number']]
        when '$bigint' then v['$bigint'].to_i
        when '$utf16'
          v['$utf16'].map { |u| u.chr(Encoding::UTF_8) }.join
        when '$undefined' then nil
        else v.transform_values { |x| decode(x) }
        end
      else
        v.transform_values { |x| decode(x) }
      end
    else v
    end
  end

  # encode is the inverse: NaN, Infinity and -0 have no JSON spelling of their own.
  def self.encode(v)
    case v
    when Float
      return { '$number' => 'NaN' } if v.nan?
      return { '$number' => v.positive? ? 'Infinity' : '-Infinity' } if v.infinite?
      return { '$number' => '-0' } if v.zero? && (1.0 / v).negative?
      v
    when Array then v.map { |x| encode(x) }
    when Hash then v.transform_values { |x| encode(x) }
    else v
    end
  end

  def self.call(name, *args)
    stdin, stdout = proc
    LOCK.synchronize do
      stdin.puts(JSON.generate({ name: name, args: args.map { |a| encode(a) } }))
      stdin.flush
      line = stdout.gets
      raise 'go-anything: the bridge closed the pipe' if line.nil?
      reply = JSON.parse(line)
      raise reply['error'] if reply['error']
      decode(reply['ok'])
    end
  end

  def self.close
    return unless @proc
    stdin, = @proc
    stdin.close
    @proc = nil
  end
  def self.pad(*args)
    GoPort.call("pad", *args)
  end
  def self.repeat(*args)
    GoPort.call("repeat", *args)
  end

end
